add('E03','教练决策与 PM 确认分工','P0','PM / 企业教练 / 统筹人','有需升级决策的问题或汇报事项。','统筹反馈|PM 上报教练决策|回到规定的 PM 确认流程','反馈、决策和最终确认各有明确责任与状态|教练决策不自动替代 PM 的最终回写确认','各角色动作、决策意见和最终确认审计')
add('E04','成果归属与附件可用','P0','成果提交人 / PM','一份经确认的成果含真实文件附件。','从成果库及任务详情打开|查看或下载附件|对照名称、项目、任务和来源','文件可访问且内容正确，中文文件名无乱码|归属与来源准确；无权账号不能通过附件地址越权读取','成果及附件 ID、文件打开结果与权限结果')
add('E05','成果更新不丢历史','P1','有成果维护权限的人员','同一成果准备初稿和修订稿。','按系统既定版本或修订机制更新|复查旧记录、来源和关联任务','当前成果清楚，历史可追溯|修订不丢原文件或错误替换另一成果，不重复关联','更新前后文件、版本或修订审计')
add('E06','跨模块数量与状态一致','P1','管理者','一个项目含未解决问题、已关闭问题及多项成果。','比较项目、推进表、任务详情、问题中心及成果库|处理一项问题后复查','相同口径下数量和状态一致|加载失败、无权限和确实无记录分别显示','各页面同一时点数据核算表')

add('F01','会议原始内容完整保留','P0','会议创建人 / PM','准备包含分条事实、表格和跨页内容的会议文件。','上传并解析|逐条核对原文与提取事实','重要事实不遗漏、不同条目不串行|原始文件、事实及页码或段落定位可追溯','原文件、事实清单与逐条覆盖核对')
add('F02','AI 建议可核对与选择','P0','会议审核人','会议含进展、问题、成果与计划调整。','查看每条 AI 建议及来源|修改、排除部分建议|核对剩余待确认项','事实与推断有清楚边界；重要字段有依据|有歧义时标为待确认，不编造负责人、日期或完成情况','建议、来源定位与人工选择记录')
add('F03','会议选择性回写与防重复','P0','有相应权限的 PM / 统筹人','已审核部分会议进展，另有未批准的计划变更。','仅应用批准的建议|重试同一应用操作|检查任务、问题和计划','只写入获准范围，计划结构变更按相应权限审批|重复操作不重复写入，未选中内容保留待处理','建议与业务记录 ID、审计和数量对照')
add('F04','会议处理失败与恢复','P1','会议创建人','大文件或中途失败的分析任务。','触发可控失败或超时|重新进入页面并重试|核对处理状态及最终产物','处理中、失败、可重试、完成状态真实可见|重试不漏事实或重复回写；恢复能力边界明确','处理日志、失败原因、重试与事实核对结果')
add('F05','启动会不改变常规立项门槛','P0','PM / 企业教练','项目已通过常规立项审核，另有历史待启动项目。','创建或确认启动会审核包|对照常规立项状态与历史兼容规则','新项目审核通过即进入进行中；启动会是会议和提案审核流程|不混用历史 pending_kickoff 作为新项目强制门槛','项目状态与启动会审核记录')
add('F06','AI 样本质量验收','P1','业务验收人','准备人工核对过的普通、长文、模糊、矛盾及失败样本。','逐份比较事实覆盖、归属、责任人与日期|记录错误和人工修订|核对失败样本表现','业务关键事实完整、归属准确；不得无依据新增事实|每个样本有预期与结果；未满足门槛的样本保留问题单，不用模型调用成功代替质量通过','评测样本、人工答案、结果对照及遗留问题','unverified','完整优化路径与会议分析记录','建议质量门槛')

add('G01','结束申请有明确完成依据','P0','PM','进行中项目有最终交付与验收材料。','填写结束申请|检查未完确认、待决策问题、待审成果或成员申请等阻断项','申请仅从进行中发起；完成材料可核对|有阻断项时明确拒绝并指出待处理事项','结束材料、阻断清单与申请结果')
add('G02','结束审核与取消退回','P0','PM / 企业教练','有待审核的结束申请。','PM 测试合法取消|教练填写意见退回|重新提交后审核通过','取消或退回恢复进行中；审核通过进入已结束|项目与申请状态配对，重复审核不产生冲突','项目和申请状态、意见与审计')
add('G03','结束冻结与只读保护','P0','项目成员 / PM','分别准备结束审核中、已结束、已归档项目。','尝试新增汇报、修改任务和写入业务记录|查看历史与附件','按当前规则冻结写入，前后端一致|已存在历史、来源与附件保持可查，拒绝操作有明确提示','各状态写入拒绝结果与只读截图')
add('G04','归档权限与完整保留','P0','技术管理员 / 普通角色','已结束项目包含任务、会议、问题和成果。','普通角色尝试归档|技术管理员执行归档|核对归档后的记录与访问范围','仅技术管理员可从已结束归档|归档保留完整历史与权限边界；归档不等于删除','归档动作、状态、历史对象与审计')

add('H01','界面布局与中文可读性','P1','业务验收人','按桌面 1366×768、1440×900 和窄屏 390×844 验收。','执行建项、编辑方案、检查进度及审核|输入长名称、长标准与多名协助人','标题、正文、辅助信息层次明确；控件不重叠、裁切或挡住主要按钮|长文本有全文入口；日期、人员和反馈清楚，颜色不能是唯一的状态依据','各页面各尺寸截图；记录实际浏览器','history','2026-10-12 立项前端视觉验收（仅立项子范围）','体验门槛')
add('H02','操作反馈与输入保留','P1','业务验收人','模拟弱网、断网、保存失败、权限不足和重复点击。','在关键表单执行保存或提交|失败后修正并重试|返回与刷新核对','进行中状态明确，防止重复操作|成功提示对应实际写入；失败保留输入并说明原因，返回路径清晰','异常操作录屏、接口及前后字段对照')
add('H03','完整业务链路与证据','P0','公司管理 / PM / 教练 / 成员','使用独立账号、干净验收项目和具代表性的多任务样例。','建项、下发、编制、退回重提、批准|成员汇报、PM 确认、问题处理、成果核对|申请结束、审核及归档','完整链路可由真实业务人员独立完成|每次状态变化与数据回写一致，负向权限验证通过，无 P0 阻断项','全流程录像或步骤截图、对象 ID、问题单和签收记录')
add('H04','V2 测试与构建门禁','P0','开发 / 测试','记录本次完整版本、工作区差异、依赖与运行配置。','执行本次 V2 单元、契约、类型检查及生产构建|执行相关后端检查与回归|保留命令、时间与退出码','当前待交付版本检查通过，无未解释失败|测试范围与未覆盖项明确，历史通过不代替本次复测','本次命令及日志、版本标识；可参考 10月12日 2080 后端、170 单元、523 契约历史结果')
add('H05','构建体积与操作性能','P1','开发 / 测试','采用同设备、浏览器和网络，准备 30 项重点工作、300 项任务的验收样例。','运行项目原有 bundle 检查|记录首屏、筛选、分组与详情响应|检查请求数量及重复请求','沿用当前体积预算：初始 JS 340000/110000，CSS 140000/24000，最大路由 140000/36000，均为原始/gzip 字节|建议体验门槛：数据已加载后筛选及折叠可见反馈 ≤500ms；记录实测值，超限需问题单或验收人书面接受','bundle 输出、设备网络条件、计时和请求记录','unverified','当前 bundle-baseline.json；体验计时为本文件建议','技术门槛 / 建议性能门槛')
add('H06','部署版本、迁移与恢复','P0','发布负责人','准备隔离环境、备份及可追溯发布包；生产另走既定授权。','核对前端 V2、后端和数据库迁移版本|在隔离目标数据库验证升级、必要回退及备份恢复|部署后执行登录与主流程冒烟','源码、构建、运行版本一致，能确定验收的是哪一版|数据迁移和恢复有实际证据；本地 SQLite 结果不替代目标 PostgreSQL 验证；上线结论仅适用于已验环境','提交或工作区快照标识、镜像摘要、迁移版本、恢复记录及冒烟结果')

assert len(CASES) == 60
assert len({x['id'] for x in CASES}) == 60

DATA = dict(version=1, date='2026-10-15', modules=[dict(id=a,title=b,description=c) for a,b,c in MODULES], cases=CASES)
template = (OUT / 'acceptance_template.html').read_text(encoding='utf-8')
payload = json.dumps(DATA, ensure_ascii=False).replace('<', '\\u003c')
result = template.replace('/*__ACCEPTANCE_DATA__*/', 'const DATA = '+payload+';')
dest = OUT / '项目管理系统验收标准-2026-10-15.html'
dest.write_text(result, encoding='utf-8')
print(json.dumps(dict(path=str(dest), cases=len(CASES), modules=len(MODULES), bytes=dest.stat().st_size),ensure_ascii=False))
